// Alias `int` to a concrete integer type.
type int = i32;

fn array_sum(a: Vec<int>, b: Vec<int>) -> Vec<int> {
    assert_eq!(
        a.len(),
        b.len(),
        "Input arrays must have the same length"
    );
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x + y)
     .collect()
}

